(x, y, t) => {
  const cx = 240, cy = 120;
  let sx = x, sy = y;
  const w1x = Math.sin(sx*0.018+t*0.25)*18 + Math.cos(sy*0.022-t*0.18)*12;
  const w1y = Math.cos(sy*0.02-t*0.22)*18 + Math.sin(sx*0.016+t*0.3)*12;
  sx += w1x; sy += w1y;
  const w2x = Math.sin(sx*0.025+t*0.15)*8 + Math.cos(sy*0.03-t*0.12)*6;
  const w2y = Math.cos(sy*0.028-t*0.18)*8 + Math.sin(sx*0.022+t*0.2)*6;
  sx += w2x; sy += w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.5],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.4],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.3],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.55],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.45],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 1.8, 0.35],
    [400+Math.cos(t*0.55+2)*80, 220+Math.sin(t*0.75+4)*60, 0.065, 2.4, 0.5]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for(const [sX,sY,f,sp,amp] of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=amp*Math.sin(d*f-t*sp); iS+=amp*Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=amp*0.3*Math.sin(d*f*2.5-t*sp*1.3+0.7); iS2+=amp*0.3*Math.sin(d*f*1.8+t*sp*0.9+2.3);
  }
  const act=(aS+aS2)/5.2, inh=(iS+iS2)/5.2;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.06+sy*0.01-t*0.7)+Math.sin(-sx*0.02+sy*0.05+t*0.9))/2.5+Math.sin((sx+sy)*0.12+t*2.5)*0.15+Math.sin((sx-sy)*0.1-t*2)*0.15+Math.sin((sx*0.7+sy*1.3)*0.08+t*1.8)*0.1;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.08-ang*2-t*2)*0.5+Math.sin(dist*0.03+ang*6-t*0.8)*0.3)*0.3;
  const cell1=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5);
  const cell2=Math.tanh((Math.sin(sx*0.25+t*0.3)*Math.sin(sy*0.22-t*0.2)+Math.sin((sx-sy)*0.18+t*0.7)*0.4)*1.2);
  const fine=Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*Math.sin((sx+sy)*0.3+t*2)*0.12;
  const raw=act-inh*0.7+bg*0.3+spiral+cell1*0.2+cell2*0.1+fine;
  const reaction=Math.tanh(raw*2.0);
  const reaction2=Math.tanh((act*0.5+iS2*0.3-aS2*0.2+bg*0.4)*1.5);
  const depth=reaction*0.7+reaction2*0.3;
  const v=depth*0.5+0.5;
  const pal=[[5,12,45],[10,40,85],[15,75,120],[20,120,135],[40,155,130],[120,180,100],[200,195,80],[230,165,65],[220,110,55],[180,60,60],[120,30,65],[60,15,55],[25,12,48],[5,12,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.75?1.12:(Math.abs(reaction)>0.5?1.05:1.0);
  const glow=Math.max(0,reaction)*0.1;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*40)|0)
  ];
}
